draw:
var g = 9.8;
var r = p.radius, m = p.mass, k = p.vtop;
var vtopCrit = Math.sqrt(g * r);
var vtop = k * vtopCrit;

// integrate angle from top
var dt = 0.004;
var steps = Math.floor((t % 8) / dt);
if (steps > 2400) steps = 2400;
var phi = 0.0001;
var i, v2;
for (i = 0; i < steps; i++) {
  v2 = vtop * vtop + 2 * g * r * (1 - Math.cos(phi));
  if (v2 < 0) v2 = 0;
  phi += (Math.sqrt(v2) / r) * dt;
}
phi = phi % (2 * Math.PI);

v2 = vtop * vtop + 2 * g * r * (1 - Math.cos(phi));
if (v2 < 0) v2 = 0;
var Tension = m * v2 / r - m * g * Math.cos(phi);
var slack = Tension < 0;

var Ttop = m * vtop * vtop / r - m * g;
var vbot2 = vtop * vtop + 4 * g * r;
var Tbot = m * vbot2 / r + m * g;

var cx = W * 0.36, cy = H * 0.52;
var R = Math.min(W * 0.24, H * 0.36);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);

// phi measured from the top, clockwise
var bx = cx + R * Math.sin(phi), by = cy - R * Math.cos(phi);

ctx.strokeStyle = slack ? C.faint : C.ink;
if (slack) ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(bx, by); ctx.stroke();
ctx.setLineDash([]);

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var th = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(th - 0.4), y1 - 7 * Math.sin(th - 0.4));
  ctx.lineTo(x1 - 7 * Math.cos(th + 0.4), y1 - 7 * Math.sin(th + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.lineWidth = 1;
}

// weight arrow on the ball
arrow(bx, by, bx, by + R * 0.34, C.figure);
ctx.fillStyle = C.figure;
ctx.fillText("mg", bx + 5, by + R * 0.34 + 2);

// tension arrow, along the string toward the centre
if (!slack) {
  var ux = (cx - bx), uy = (cy - by);
  var L = Math.sqrt(ux * ux + uy * uy); ux /= L; uy /= L;
  var tl = R * 0.22 + R * 0.5 * Math.min(1, Tension / (6 * m * g));
  arrow(bx, by, bx + ux * tl, by + uy * tl, C.accent);
  ctx.fillStyle = C.accent;
  ctx.fillText("T", bx + ux * tl - 14, by + uy * tl - 4);
}

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(bx, by, 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fill();
ctx.fillText("top", cx - 10, cy - R - 8);
ctx.fillText("bottom", cx - 20, cy + R + 18);

// tension bar chart: top, current, bottom
var bx0 = W * 0.64, bw = W * 0.08, base = H * 0.82;
var maxT = Math.max(Tbot, 1);
var vals = [Ttop, Tension, Tbot];
var names = ["T top", "T now", "T bot"];
var j;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(bx0 - 8, base); ctx.lineTo(W * 0.98, base); ctx.stroke();
for (j = 0; j < 3; j++) {
  var val = vals[j];
  var h = (H * 0.6) * Math.max(0, val) / maxT;
  ctx.fillStyle = val <= 0 ? C.faint : (j === 1 ? C.accent : C.figure);
  ctx.fillRect(bx0 + j * bw * 1.5, base - h, bw, Math.max(h, 2));
  ctx.fillStyle = C.ink;
  ctx.fillText(names[j], bx0 + j * bw * 1.5 - 2, base + 14);
  ctx.fillText(val > 0 ? val.toFixed(1) : "0", bx0 + j * bw * 1.5 - 2, base - h - 5);
}
ctx.fillStyle = C.ink;
ctx.fillText("string tension (N)", bx0 - 8, H * 0.14);

out.note = "v_top = " + vtop.toFixed(2) + " m/s (critical " + vtopCrit.toFixed(2) + "),  T at top = " + (Ttop > -0.0001 ? Ttop.toFixed(2) + " N" : "string would go slack") + ",  v at bottom = " + Math.sqrt(vbot2).toFixed(2) + " m/s,  T at bottom = " + Tbot.toFixed(2) + " N";
